@startuml

class Person {
  + personID : int
  + phoneNumber : string
  + keywords : string[]
}

class Institution {
  + institutionCode : string
}

class Article {
  + DOI : string
  + title : string
}

class PeerReviewedPaper extends Article {
  + citationCount : int
}

class TechnicalReport extends Article {
}

class AuthorPosition {
  + position : int
}

class Publisher {
  + name : string
}

class Journal {
  + name : string
  + impactFactor : float
}

Person "1" -- "*" Article : authors
Person "0..*" -- "0..*" Article : reviews
Person "*" -- "1" Institution : works for
Institution "1" -- "*" TechnicalReport : publishes
Publisher "1" -- "*" Journal : publishes
Institution "*" -- "*" Journal : subscribes
Journal "1" -- "*" PeerReviewedPaper : publishes

Article "1" *-- "*" AuthorPosition
AuthorPosition "*" -- "1" Person : author

@enduml

